// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DE HUBS (MAGALU, OLIST, ANYMARKET, SKYHUB)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

let hubOrigem = 'Magalu';
if (body.Marketplace || body.partner_id || body.anymarket_id) hubOrigem = 'AnyMarket';
else if (body.channel || body.olist_order_id) hubOrigem = 'Olist';
else if (body.skyhub_id || body.code) hubOrigem = 'SkyHub';
else if (body.Magalu || body.LuizaLabs) hubOrigem = 'Magalu';

const customer = body.Customer || body.customer || body.cliente || {};
let rawPhone = (customer.Phone || customer.phone || body.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (customer.Name || customer.name || 'Cliente Hub').trim();
const clienteEmail = (customer.Email || customer.email || '').trim().toLowerCase();
const clienteDoc = (customer.Cpf || customer.cpf || customer.document || '').toString().replace(/\D/g, '');

const numeroPedido = parseInt(body.Id || body.id || body.order_id || Date.now(), 10);
const valorTotal = parseFloat(body.Total || body.total || body.total_amount || 0);
const status = (body.Status || body.status || '').toLowerCase();

let statusOperacional = 'Pendente';
if (['approved', 'paid', 'pago', 'faturado'].includes(status)) {
  statusOperacional = 'Pago';
} else if (['canceled', 'cancelado'].includes(status)) {
  statusOperacional = 'Cancelado';
}

const dedupHash = crypto.createHash('sha256').update(`${hubOrigem}_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    hub_origem: hubOrigem,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_doc: clienteDoc,
    valor_total: valorTotal,
    status_operacional: statusOperacional
  }
}];
